:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
  --border-radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.game-container {
  background-color: var(--card);
  padding: 24px;
  border-radius: var(--border-radius);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

h1 {
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--accent);
}

.score {
  font-size: 1.2rem;
  font-weight: 600;
  background-color: var(--primary);
  padding: 4px 12px;
  border-radius: 20px;
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  background-color: #0d0d1a;
  border-radius: 8px;
  overflow: hidden;
  border: 2px solid var(--primary);
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background-color: rgba(13, 13, 26, 0.92);
  display: flex;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: 20px;
  transition: opacity 0.3s;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay-content {
  max-width: 300px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.overlay h2 {
  font-size: 1.5rem;
  color: var(--accent);
}

.overlay p {
  font-size: 1rem;
  line-height: 1.5;
  color: var(--text-muted);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.btn {
  background-color: var(--primary);
  color: var(--text);
  border: 2px solid transparent;
  padding: 10px 24px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s, border-color 0.2s, transform 0.1s;
  font-family: inherit;
}

.btn:hover {
  background-color: #1a4a7a;
  border-color: var(--accent);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
  background-color: #0a2a4a;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.3rem;
  }
  .btn {
    padding: 8px 16px;
    font-size: 0.9rem;
  }
}

(function () {
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const scoreSpan = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlayTitle');
  const overlayText = document.getElementById('overlayText');
  const startBtn = document.getElementById('startBtn');
  const pauseBtn = document.getElementById('pauseBtn');
  const restartBtn = document.getElementById('restartBtn');

  const GRID_SIZE = 20;
  const CELL_SIZE = canvas.width / GRID_SIZE;

  let snake, food, direction, nextDirection, score, gameOver, paused, gameLoop;

  function init() {
    snake = [{ x: 10, y: 10 }];
    direction = { x: 0, y: 0 };
    nextDirection = { x: 0, y: 0 };
    score = 0;
    gameOver = false;
    paused = true;
    placeFood();
    updateScore();
    draw();
    showOverlay('How to Play', 'Use arrow keys to move. Eat the red apple to grow and score points. Avoid walls and yourself!', 'Start Game');
    pauseBtn.textContent = 'Resume';
    pauseBtn.disabled = true;
  }

  function placeFood() {
    let newFood;
    do {
      newFood = {
        x: Math.floor(Math.random() * GRID_SIZE),
        y: Math.floor(Math.random() * GRID_SIZE)
      };
    } while (snake.some(segment => segment.x === newFood.x && segment.y === newFood.y));
    food = newFood;
  }

  function updateScore() {
    scoreSpan.textContent = score;
  }

  function showOverlay(title, text, btnText) {
    overlayTitle.textContent = title;
    overlayText.textContent = text;
    startBtn.textContent = btnText;
    overlay.classList.remove('hidden');
  }

  function hideOverlay() {
    overlay.classList.add('hidden');
  }

  function draw() {
    ctx.fillStyle = '#0d0d1a';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw grid lines (subtle)
    ctx.strokeStyle = '#1a1a2e';
    ctx.lineWidth = 0.5;
    for (let i = 0; i <= GRID_SIZE; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL_SIZE, 0);
      ctx.lineTo(i * CELL_SIZE, canvas.height);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * CELL_SIZE);
      ctx.lineTo(canvas.width, i * CELL_SIZE);
      ctx.stroke();
    }

    // Draw food
    ctx.fillStyle = '#e94560';
    ctx.fillRect(food.x * CELL_SIZE, food.y * CELL_SIZE, CELL_SIZE, CELL_SIZE);

    // Draw snake
    snake.forEach((segment, index) => {
      ctx.fillStyle = index === 0 ? '#4ecca3' : '#2ecc71';
      ctx.fillRect(segment.x * CELL_SIZE, segment.y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
      // Add pixel detail
      ctx.fillStyle = 'rgba(255,255,255,0.2)';
      ctx.fillRect(segment.x * CELL_SIZE + 2, segment.y * CELL_SIZE + 2, CELL_SIZE - 4, CELL_SIZE - 4);
    });
  }

  function step() {
    if (paused || gameOver) return;

    direction = { ...nextDirection };
    if (direction.x === 0 && direction.y === 0) return;

    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    // Check wall collision
    if (head.x < 0 || head.x >= GRID_SIZE || head.y < 0 || head.y >= GRID_SIZE) {
      endGame();
      return;
    }

    // Check self collision
    if (snake.some(segment => segment.x === head.x && segment.y === head.y)) {
      endGame();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      updateScore();
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function endGame() {
    gameOver = true;
    paused = true;
    clearInterval(gameLoop);
    showOverlay('Game Over', `Your score: ${score}`, 'Play Again');
    pauseBtn.textContent = 'Pause';
    pauseBtn.disabled = true;
  }

  function startGame() {
    init();
    paused = false;
    hideOverlay();
    pauseBtn.textContent = 'Pause';
    pauseBtn.disabled = false;
    clearInterval(gameLoop);
    gameLoop = setInterval(step, 120);
  }

  function togglePause() {
    if (gameOver) return;
    paused = !paused;
    if (paused) {
      pauseBtn.textContent = 'Resume';
      showOverlay('Paused', 'Press Resume or the Pause button to continue.', 'Resume');
    } else {
      pauseBtn.textContent = 'Pause';
      hideOverlay();
    }
  }

  function restartGame() {
    clearInterval(gameLoop);
    init();
    paused = false;
    hideOverlay();
    pauseBtn.textContent = 'Pause';
    pauseBtn.disabled = false;
    gameLoop = setInterval(step, 120);
  }

  // Keyboard controls
  document.addEventListener('keydown', (e) => {
    if (gameOver) return;
    const key = e.key;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(key)) {
      e.preventDefault();
      if (paused) return;
      if (key === 'ArrowUp' && direction.y !== 1) nextDirection = { x: 0, y: -1 };
      else if (key === 'ArrowDown' && direction.y !== -1) nextDirection = { x: 0, y: 1 };
      else if (key === 'ArrowLeft' && direction.x !== 1) nextDirection = { x: -1, y: 0 };
      else if (key === 'ArrowRight' && direction.x !== -1) nextDirection = { x: 1, y: 0 };
    }
    if (key === ' ' || key === 'p' || key === 'P') {
      e.preventDefault();
      if (!paused || gameOver) togglePause();
    }
  });

  // Button events
  startBtn.addEventListener('click', () => {
    if (gameOver) restartGame();
    else if (paused) togglePause();
    else startGame();
  });

  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restartGame);

  // Initialize
  init();
})();
